+++ b/observability/metrics/histogram.go
@@ -12,6 +12,22 @@
 func NewTokenLifecycleBurnup(name string, buckets []float64) *Histogram {
-    // existing generic histo factory
+    // token lifecycle burnup uses exponential buckets plus heavy-tail slots
+    if len(buckets) == 0 {
+        buckets = append(makeExponentialBuckets(0.01, 2.0, 40), 1024, 4096)
+    }
+    h := NewHistogram(name, buckets)
+    return h
 }

+// instrumentation helper called at stage boundaries
+func RecordTokenStage(ctx context.Context, h *Histogram, tenant, model, stage string, tokens float64) {
+    h.WithLabels("tenant", tenant, "model", model, "stage", stage).Observe(tokens)
+}
